let state=newGame(),selectedRegion='cisalpine',selectedArmy='xiii',tab='map',ordering=false,speed=1,playing=false,timer=null,toast='',chosenFaction='caesar',chosenScenario='historical',chosenDifficulty='standard',chosenHandicap=false,chosenGuide=true,chosenSlot='1',setupOpen=false,setupRequired=false,panelOpen=false,mapMode='political',view=initialView(),boardSelected=null,boardView='all',chosenMandate=true,eastSelected=null,eastCamera='all',eastMode='political';
const received=receiveHandoff(sessionStorage,'campaign',upgradeSave);
