  document.querySelectorAll('[data-east-camera]').forEach(el=>el.onclick=()=>{eastCamera=el.dataset.eastCamera;render()});
  const eastEmbassy=document.querySelector('#east-embassy');if(eastEmbassy)eastEmbassy.onclick=()=>{const r=sendEmbassyToSeres(state);flash(r.ok?(lang==='zh'?'使者已启程':'Envoys have set out'):(lang==='zh'?'条件不足':'Conditions not met'));render()};
  
  document.querySelectorAll('[data-board-view]').forEach(el=>el.onclick=()=>{boardView=el.dataset.boardView;boardSelected=null;render()});
  document.querySelectorAll('[data-board-node]').forEach(el=>{const select=()=>{boardSelected=el.dataset.boardNode;render();[...document.querySelectorAll('g[data-board-node]')].find(node=>node.dataset.boardNode===boardSelected)?.focus()};el.onclick=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}});
  document.querySelectorAll('[data-recognize-movement]').forEach(el=>el.onclick=()=>{const yes=el.dataset.recognition==='yes',result=recognizeMovement(state,state.player,el.dataset.recognizeMovement,yes);if(result.ok){render();flash(yes?(lang==='zh'?'已公开承认该报告中的运动。':'Recognition of the reported movement declared.'):(lang==='zh'?'已撤回承认。':'Recognition withdrawn.'))}else flash(lang==='zh'?'行动不可用：请检查国库及已有立场。':'Unavailable: check treasury and your existing position.')});
  document.querySelector('#movement-contact-send')?.addEventListener('click',()=>{const [id,representative]=document.querySelector('#movement-contact').value.split('|'),result=offerMovementSupport(state,state.player,id,representative);if(result.ok){render();flash(lang==='zh'?'资助提议已寄出；回信约需4个月。':'Support offer sent; allow about four months for a reply.')}else flash(lang==='zh'?'无法派出：请检查联系、国库及已有提议。':'Unavailable: check the contact, treasury and pending offers.')});
  document.querySelectorAll('[data-movement-response]').forEach(el=>el.onclick=()=>{const result=respondToMovement(state,state.player,el.dataset.movementId,el.dataset.movementResponse);if(result.ok){render();flash(result.settled?(lang==='zh'?'政治争议已解决。':'Political dispute settled.'):(lang==='zh'?'已作出回应；争议仍在继续。':'Response made; the dispute continues.'))}else flash(lang==='zh'?'行动不可用：请检查局势与国库。':'Action unavailable; check conditions and treasury.')});
  document.querySelectorAll('[data-national-idea]').forEach(el=>el.onclick=()=>{const id=el.dataset.nationalIdea,known=state.inventions[state.player].knownIdeas.includes(id),result=known?equipIdea(state,state.player,id):startResearch(state,state.player,id);if(result.ok){render();flash(lang==='zh'?'理念工作已开始，需要数月完成。':'Idea work started; completion takes several months.')}else flash(lang==='zh'?'无法开始：请检查资源、研究或理念槽位。':'Unavailable: check resources, research and idea slots.')});
  document.querySelectorAll('[data-religion-action]').forEach(el=>el.onclick=()=>{const result=religiousPolicy(state,state.player,el.dataset.institution,el.dataset.religionAction);if(result.ok){render();flash(lang==='zh'?'政策已实施。':'Policy enacted.')}else flash(lang==='zh'?'政策不可用：请检查国库、控制权和已有调查。':'Policy unavailable; check treasury, control and pending inquiries.')});
  document.querySelector('#political-contact-send')?.addEventListener('click',()=>{const [target,person,representative]=document.querySelector('#political-contact').value.split('|');const result=offerPoliticalContact(state,state.player,target,person,representative);if(result.ok){render();flash(lang==='zh'?'秘密提议已派出；回信约需4个月。':'Secret offer sent; allow about four months for a reply.')}else flash(lang==='zh'?'无法派出：请检查联系人、国库及已有提议。':'Unavailable: check contacts, treasury and existing offers.')});
  document.querySelector('#coalition-propose')?.addEventListener('click',()=>{const first=document.querySelector('#coalition-first').value,second=document.querySelector('#coalition-second').value,target=document.querySelector('#coalition-threat').value;const result=formCoalition(state,state.player,[first,second],target,estimatedStrength);if(result.ok){render();flash(lang==='zh'?'防御联盟已成立。':'Defensive coalition formed.')}else flash(lang==='zh'?'联盟未能成立：成员须不同，且各方须有共同威胁、足够信任与资金。':'Coalition declined: choose distinct parties with a shared perceived threat, sufficient trust and funds.')});
  document.querySelectorAll('[data-leave-coalition]').forEach(el=>el.onclick=()=>{if(leaveCoalition(state,el.dataset.leaveCoalition,state.player).ok){render();flash(lang==='zh'?'已退出联盟，信誉和关系下降。':'Left the coalition; credibility and relations fell.')}});
  document.querySelector('#agreement-type')?.addEventListener('change',e=>{const note=document.querySelector('#agreement-guide');if(note)note.textContent=agreementGuide(e.target.value)});document.querySelector('#agreement-propose')?.addEventListener('click',()=>{const target=document.querySelector('#agreement-target').value,type=document.querySelector('#agreement-type').value,secret=document.querySelector('#agreement-secret').checked;const result=proposeAgreement(state,state.player,target,type,{secret});if(result.ok){render();flash(lang==='zh'?'条约已达成。':'Agreement concluded.')}else flash(lang==='zh'?'提议未能达成：请检查关系、信誉、国库及当前状态。':'Proposal declined or unavailable; check relations, credibility, treasury and current conditions.')});
  document.querySelectorAll('[data-breach]').forEach(el=>el.onclick=()=>{const result=terminateAgreement(state,el.dataset.breach,state.player);if(result.ok){render();flash(lang==='zh'?'已违约终止条约，信誉和关系下降。':'Agreement breached; credibility and relations fell.')}});
  const finalize=document.querySelector('#finalize-campaign');if(finalize)finalize.onclick=()=>{const result=finalizeCampaign(state);if(!result.ok)return;try{const saved=archives().filter(a=>a.id!==result.archive.id);saved.unshift(result.archive);localStorage.setItem('spqr-legacy-archive',JSON.stringify(saved.slice(0,20)))}catch{delete state.world.dynasties.finalized;flash(lang==='zh'?'无法写入本地档案。':'Could not write the local archive.');return}render()};
  if(tab==='government')bindGenealogy(document.querySelector('.inspector'),state,lang==='zh',render);
  if(tab==='chronicle')renderChronicle({root:document.querySelector('#chronicle-root'),state,language:lang,onRegion:id=>{selectedRegion=id;tab='map';panelOpen=true;render()},onBattle:id=>{const e=state.chronicle?.entries.find(x=>x.battleId===id&&x.kind==='battle');if(!e)return;const root=document.querySelector('#chronicle-root');root.innerHTML='<button id="history-back">'+(lang==='zh'?'返回编年史':'Back to Chronicle')+'</button><article class="dispatch"><strong>'+esc(chronicleDate(e,lang))+'</strong><p>'+esc(formatChronicleEntry(e,lang))+'</p></article>';root.querySelector('#history-back').onclick=render},onArmies:e=>{selectedArmy=state.armies.find(a=>a.owner===state.player&&e&&(a.region===e.region||adjacent(a.region).some(route=>route.to===e.region)))?.id||null;tab='military';panelOpen=true;render()},onCharacter:id=>{const person=state.world.characters[id];if(person?.faction===state.player&&CHARACTER_CATALOG[id]){const people=Object.values(state.world.characters).filter(c=>c.faction===state.player&&CHARACTER_CATALOG[c.id]),index=people.findIndex(c=>c.id===id);if(index<0)return;state.world.dynasties.treePage=Math.floor(index/100);tab='government';panelOpen=true;render();const button=[...document.querySelectorAll('[data-gene-person]')].find(el=>el.dataset.genePerson===id);if(button){button.click();button.scrollIntoView({block:'nearest',inline:'nearest'})}else flash(lang==='zh'?'无法打开此人物档案。':'Could not open this person’s record.')}else if(person&&CHARACTER_CATALOG[id])openAtlas('person='+encodeURIComponent(id));else flash(lang==='zh'?'该人物档案不可用。':'This person’s record is unavailable.')}});
  document.querySelector('#lang').onclick=()=>{lang=lang==='en'?'zh':'en';localStorage.setItem('spqr-lang',lang);render()};
  const openAtlas=(section='')=>{if(!['caesar','senate'].includes(state.player)){flash(lang==='zh'?'此剧本请使用当前战役地图。':'Use the campaign map for this scenario.');return}try{stageHandoff(sessionStorage,state,'atlas');stop();location.assign('./map-lab/'+(section?'#'+section:''))}catch{flash(lang==='zh'?'无法切换：浏览器未能暂存战役，请检查存储设置。':'Could not transfer the campaign. Check browser storage settings.')}};
  document.querySelector('#open-intelligence')?.addEventListener('click',()=>openAtlas('factions'));
  document.querySelector('#open-atlas').onclick=()=>openAtlas();
  document.querySelector('#new').onclick=()=>{stop();toast='';setupRequired=false;setupOpen=true;render()};
  const choice=document.querySelector('#faction-choice');if(choice)choice.onchange=e=>{chosenFaction=e.target.value};
  const scenarioChoice=document.querySelector('#scenario-choice');if(scenarioChoice)scenarioChoice.onchange=e=>{chosenScenario=e.target.value;render()};
  const difficultyChoice=document.querySelector('#campaign-difficulty');if(difficultyChoice)difficultyChoice.onchange=e=>{chosenDifficulty=e.target.value};const handicapChoice=document.querySelector('#campaign-handicap');if(handicapChoice)handicapChoice.onchange=e=>{chosenHandicap=e.target.checked};
